    private Map<String, List<String>> commentsMap;

    public CommentsConfiguration() {
        this.commentsMap = new HashMap<>();
    }

    public void setComment(String path, String line) {
        if (commentsMap.containsKey(path)) {
            commentsMap.get(path).add(line);
        } else {
            List<String> lines = new ArrayList<>();
            lines.add(line);
            commentsMap.put(path, lines);
        }
    }

    public Map<String, List<String>> getComments() {
        return Collections.unmodifiableMap(commentsMap);
    }

    public Map<String, List<String>> getAllComments() {
        return this.getComments();
    }
}

